SELECT p90, mortality_rate, avg_critical_labs, avg_critical_labs_cohort FROM (SELECT percentile_cont(0.9) WITHIN GROUP (ORDER BY value) AS p90, CAST(COUNT(CASE WHEN deathtime IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(subject_id), 0) AS mortality_rate, AVG(COUNT(itemid)) AS avg_critical_labs, AVG(COUNT(itemid)) AS avg_critical_labs_cohort FROM admissions WHERE subject_id IN (SELECT subject_id FROM patients WHERE gender = 'F' AND age >= 53 AND icd_code = '30764' AND icd_version = '2018' AND anchor_year_group BETWEEN 48 AND 58') AND charttime <= 72 AND itemid IN (SELECT itemid FROM d_labitems WHERE category = 'Critical') GROUP BY subject_id) AS subquery;